(async () => {
  document.querySelector('[data-quote-open]').click();
  await new Promise(r => setTimeout(r, 400));
  const m = document.getElementById('gquote');
  const p = m.querySelector('.gquote__panel');
  const r = p.getBoundingClientRect();
  const cs = getComputedStyle(m);
  return {vw: innerWidth, docW: document.documentElement.scrollWidth,
          panel: {x: Math.round(r.x), w: Math.round(r.width), h: Math.round(r.height)},
          pos: cs.position, display: cs.display,
          parent: m.parentElement.tagName + '.' + m.parentElement.className,
          bodyOverflow: document.body.style.overflow};
})()
